// Ngân hàng câu hỏi – Tiếng Anh 10 (Global Success). Nội dung tự biên soạn.
window.QBANK = window.QBANK || [];
window.QBANK.push(
  { id: "anh10-1-01", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the word whose part in brackets is pronounced differently from the others. (Chọn từ có phần trong ngoặc [ ] phát âm khác)", options: ["[ch]ores","[ch]ildren","[ch]aracter","[ch]eck"], answer: 2, explanation: "\"character\" có \"ch\" đọc /k/; các từ còn lại \"ch\" đọc /tʃ/." },
  { id: "anh10-1-02", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nMy father is the ___ of the family; he earns money to support all of us.", options: ["homemaker","housework","chore","breadwinner"], answer: 3, explanation: "breadwinner = người trụ cột kiếm tiền nuôi gia đình, hợp với \"earns money to support all of us\"." },
  { id: "anh10-1-03", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nMy mother usually ___ dinner for the whole family.", options: ["is cooking","cook","cooks","are cooking"], answer: 2, explanation: "\"usually\" chỉ thói quen → thì hiện tại đơn; chủ ngữ số ít \"My mother\" → cooks." },
  { id: "anh10-1-04", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Speaking & Communication", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Choose the most suitable response to complete the exchange.\nMai: \"Shall I help you with the washing-up, Mum?\"\nMum: \"___\"", options: ["Yes, I do.","You're welcome.","That's very kind of you. Thanks!","No, I don't like it."], answer: 2, explanation: "Đáp lại lời đề nghị giúp đỡ bằng lời cảm ơn: \"That's very kind of you. Thanks!\"." },
  { id: "anh10-1-05", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nIn many families today, both parents go to work, so household chores are shared among all members. My brother and I are responsible ___ cleaning our own rooms and taking out the rubbish.", options: ["with","for","of","about"], answer: 1, explanation: "Cụm cố định \"be responsible for + V-ing\" = chịu trách nhiệm về việc gì." },
  { id: "anh10-1-06", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Reading", type: "tf", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nThe Nguyens live in a small flat in Da Nang. Mr Nguyen is a bus driver and Mrs Nguyen is a nurse, so they both work long hours. To make life easier, the family made a chore chart. Every week, their son Minh does the laundry and their daughter Lan does the washing-up after dinner. On Sundays, the whole family goes to the market together and Mr Nguyen does the heavy lifting. Mrs Nguyen says the chart has made the house tidier and the children more independent. Minh admits that he did not like folding clothes at first, but now he does it quickly.", statements: ["Both Mr and Mrs Nguyen have jobs outside the home.","Lan is in charge of the laundry every week.","The family goes shopping together on Sundays.","Minh has always enjoyed folding clothes."], answer: [true,false,true,false], explanation: "a) Đúng: bố là tài xế xe buýt, mẹ là y tá. b) Sai: Minh giặt đồ, Lan rửa bát. c) Đúng: \"On Sundays, the whole family goes to the market together\". d) Sai: lúc đầu Minh không thích gấp quần áo." },
  { id: "anh10-1-07", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the word that differs from the other three in the position of the main stress. (Chọn từ có trọng âm chính khác)", options: ["laundry","routine","rubbish","garbage"], answer: 1, explanation: "routine /ruːˈtiːn/ nhấn âm 2; laundry, rubbish, garbage nhấn âm 1." },
  { id: "anh10-1-08", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nMy brother usually ___ out the rubbish after dinner.", options: ["does","makes","puts","takes"], answer: 3, explanation: "Cụm cố định \"take out the rubbish\" = đổ rác." },
  { id: "anh10-1-09", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Vocabulary", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nSharing housework helps children develop a sense of ___.", options: ["responsibility","responsible","responsibly","respond"], answer: 0, explanation: "Sau \"a sense of\" cần danh từ → responsibility (tinh thần trách nhiệm)." },
  { id: "anh10-1-10", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nLook! Dad ___ the dishes in the kitchen right now.", options: ["washes","is washing","wash","washed"], answer: 1, explanation: "\"Look!\" và \"right now\" chỉ hành động đang diễn ra → hiện tại tiếp diễn \"is washing\"." },
  { id: "anh10-1-11", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Grammar", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThis week my sister ___ all the cooking because Mum is away on business.", options: ["does","do","did","is doing"], answer: 3, explanation: "Hành động tạm thời trong khoảng thời gian hiện tại (\"this week\") → hiện tại tiếp diễn \"is doing\"." },
  { id: "anh10-1-12", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Grammar", type: "mcq", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Choose the part of the sentence that contains a mistake and needs correcting. (Tìm lỗi sai)\nNowadays more and more fathers are sharing the housework, and my dad is believing that it is fair.", options: ["is believing","are sharing","that","fair"], answer: 0, explanation: "\"believe\" là động từ chỉ trạng thái, không dùng ở thì tiếp diễn → sửa \"is believing\" thành \"believes\"." },
  { id: "anh10-1-13", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nDoing chores together has many benefits. It not only reduces the burden on parents ___ also strengthens the bond between family members. Children also learn useful life skills.", options: ["but","and","or","so"], answer: 0, explanation: "Cấu trúc \"not only ... but also ...\" = không những ... mà còn ..." },
  { id: "anh10-1-14", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Reading", type: "tf", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nExperts say that children who do housework from an early age often become more confident adults. When a child tidies a room or prepares a simple meal, he or she learns to plan and finish a task. These skills are later useful at school and at work. However, parents should give children chores that suit their age. A five-year-old can set the table, while a teenager can cook or do the shopping. Parents should also praise their children's efforts instead of criticising small mistakes. In this way, housework becomes a chance to learn rather than a punishment.", statements: ["According to the passage, housework can help children become more confident.","The writer suggests that all children should do the same chores.","Cooking is mentioned as a suitable chore for teenagers.","The writer believes parents should point out every small mistake their children make."], answer: [true,false,true,false], explanation: "a) Đúng: câu đầu nêu trẻ làm việc nhà thường tự tin hơn. b) Sai: việc nhà phải phù hợp lứa tuổi. c) Đúng: \"a teenager can cook or do the shopping\". d) Sai: cha mẹ nên khen ngợi thay vì chỉ trích lỗi nhỏ." },
  { id: "anh10-1-15", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Rewrite each sentence so that its meaning stays the same, using the word(s) given in brackets.\na) My mother started working as a nurse ten years ago. (has)\nb) It isn't necessary for you to do the washing-up tonight. (have)\nc) My father earns money for the family. My mother looks after the house. (while)", answer: "a) My mother has worked (has been working) as a nurse for ten years. b) You don't have to do the washing-up tonight. c) My father earns money for the family, while my mother looks after the house.", explanation: "Mỗi câu 1/3 số điểm.\na) Hành động bắt đầu trong quá khứ, kéo dài đến nay → hiện tại hoàn thành + \"for ten years\".\nb) \"It isn't necessary for sb to do\" = \"sb doesn't have to do\".\nc) \"while\" nối hai mệnh đề tương phản; có dấu phẩy trước \"while\".\nSai thì động từ hoặc thiếu \"for/don't\" trừ một nửa số điểm của câu đó." },
  { id: "anh10-1-16", subject: "anh", grade: 10, chapter: "anh10-1", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Write a paragraph (about 100 words) describing how housework is divided in your family and how you feel about it.", answer: "Đoạn văn khoảng 100 từ: ai làm việc gì, mức độ thường xuyên, cảm nghĩ.", explanation: "Tiêu chí chấm: câu chủ đề rõ (2 điểm); nêu được ít nhất 3 thành viên và việc nhà của họ, dùng đúng thì hiện tại đơn và cụm từ \"do the laundry, take out the rubbish...\" (4 điểm); cảm nghĩ/kết luận (2 điểm); ngữ pháp, chính tả, liên kết (2 điểm).\nBài mẫu: In my family, everyone shares the housework. My father is the breadwinner, but he still does the heavy lifting and repairs things at weekends. My mother usually cooks dinner and does the shopping. My older sister does the laundry twice a week, and I am responsible for washing the dishes and taking out the rubbish every evening. On Sundays, we all clean the house together while listening to music. At first I found my chores boring, but now I feel proud because I can help my parents. I think sharing housework makes our family closer and teaches us to be responsible." },
  { id: "anh10-2-01", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the word whose part in brackets is pronounced differently from the others. (Chọn từ có phần trong ngoặc [ ] phát âm khác)", options: ["pl[a]stic","w[a]ste","s[a]ve","ch[a]nge"], answer: 0, explanation: "\"plastic\" có \"a\" đọc /æ/; các từ còn lại đọc /eɪ/." },
  { id: "anh10-2-02", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nUsing cloth bags instead of plastic ones is an ___ habit.", options: ["ecology","eco-friendly","economy","environment"], answer: 1, explanation: "Trước danh từ \"habit\" cần tính từ → eco-friendly (thân thiện với môi trường)." },
  { id: "anh10-2-03", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nLook at those dark clouds! It ___ rain.", options: ["will","would","shall","is going to"], answer: 3, explanation: "Dự đoán dựa trên dấu hiệu ở hiện tại (mây đen) → \"be going to\"." },
  { id: "anh10-2-04", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Speaking & Communication", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Choose the most suitable response to complete the exchange.\nA: \"Why don't we turn off the lights when we leave the classroom?\"\nB: \"___\"", options: ["Yes, they are.","Not at all, thanks.","That's a good idea. It saves energy.","I'm afraid I can't turn on."], answer: 2, explanation: "Đáp lại lời gợi ý \"Why don't we...?\" bằng sự đồng tình: \"That's a good idea.\"" },
  { id: "anh10-2-05", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nEvery day, people ___ a huge amount of waste, such as plastic bottles, paper and leftover food. Much of this waste ends up in landfills or in the ocean.", options: ["take","give","produce","grow"], answer: 2, explanation: "\"produce waste\" = thải ra rác; các từ khác không kết hợp nghĩa với \"waste\"." },
  { id: "anh10-2-06", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Reading", type: "tf", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nLinh's family has changed their lifestyle to become greener. Two years ago, they installed solar panels on their roof, and now their electricity bill is much lower. Instead of driving, Linh's parents take the bus to work three days a week. Linh cycles to school every day. The family also grows vegetables in pots on their balcony, so they buy fewer products wrapped in plastic. Linh says the hardest change was giving up bottled water, but now she always carries a reusable bottle.", statements: ["The family started using solar energy two years ago.","Linh's parents never drive to work.","The family grows some of their own food.","Linh found it easy to stop buying bottled water."], answer: [true,false,true,false], explanation: "a) Đúng: lắp pin mặt trời hai năm trước. b) Sai: bố mẹ đi xe buýt 3 ngày/tuần, nghĩa là những ngày khác vẫn có thể lái xe. c) Đúng: trồng rau trong chậu. d) Sai: đây là thay đổi khó nhất." },
  { id: "anh10-2-07", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the word that differs from the other three in the position of the main stress. (Chọn từ có trọng âm chính khác)", options: ["organic","recycle","pollution","energy"], answer: 3, explanation: "energy /ˈenədʒi/ nhấn âm 1; organic, recycle, pollution nhấn âm 2." },
  { id: "anh10-2-08", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nWe can reduce our carbon ___ by cycling or walking instead of driving.", options: ["footprint","footstep","footnote","footpath"], answer: 0, explanation: "\"carbon footprint\" = lượng khí thải các-bon mỗi người tạo ra." },
  { id: "anh10-2-09", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Vocabulary", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nMany families have ___ a greener lifestyle by growing their own vegetables.", options: ["adapted","admitted","adopted","applied"], answer: 2, explanation: "\"adopt a lifestyle\" = áp dụng/chọn theo lối sống; \"adapt\" = thích nghi, không hợp nghĩa." },
  { id: "anh10-2-10", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nPlastic bags ___ in this supermarket any more.", options: ["are not used","do not use","are not using","not used"], answer: 0, explanation: "Chủ ngữ \"plastic bags\" chịu tác động → câu bị động hiện tại đơn \"are not used\"." },
  { id: "anh10-2-11", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Grammar", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nA: \"Oh no, I've left my reusable bottle at home.\"\nB: \"Don't worry. I ___ you mine.\"", options: ["am going to lend","will lend","lend","am lending"], answer: 1, explanation: "Quyết định ngay lúc nói → \"will\"." },
  { id: "anh10-2-12", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Grammar", type: "mcq", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThousands of trees ___ in our city by volunteers next year.", options: ["will be planted","will plant","are planting","have planted"], answer: 0, explanation: "Cây \"được trồng\" (bị động) trong tương lai (\"next year\") → will be planted." },
  { id: "anh10-2-13", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nInstead ___ driving to school, many students in our town now ride bicycles. This helps reduce traffic jams and air pollution.", options: ["for","of","from","with"], answer: 1, explanation: "Cụm \"instead of + V-ing\" = thay vì làm gì." },
  { id: "anh10-2-14", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Reading", type: "tf", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nThe Green Club at Hoa Binh High School was set up last year by a group of grade 10 students. At first, it had only eight members, but now more than fifty students have joined. Every Friday, members collect used paper from classrooms and sell it to a recycling company. The money is used to buy plants for the schoolyard. The club is going to launch a new campaign next month to encourage students to bring their own lunch boxes. The head teacher says that the amount of rubbish at school has fallen by almost a third since the club started.", statements: ["The club was founded by teachers.","The number of members has increased greatly.","The club uses the money from recycling to buy plants.","The lunch box campaign has already finished."], answer: [false,true,true,false], explanation: "a) Sai: do học sinh lớp 10 thành lập. b) Đúng: từ 8 lên hơn 50 thành viên. c) Đúng: tiền bán giấy dùng mua cây. d) Sai: chiến dịch sẽ bắt đầu tháng sau (\"is going to launch next month\")." },
  { id: "anh10-2-15", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Rewrite each sentence so that its meaning stays the same, using the word(s) given in brackets.\na) People will recycle these bottles. (be)\nb) Volunteers cleaned the beach last Sunday. (was)\nc) I intend to buy an electric bike next month. (going)", answer: "a) These bottles will be recycled. b) The beach was cleaned by volunteers last Sunday. c) I am going to buy an electric bike next month.", explanation: "Mỗi câu 1/3 số điểm.\na) Bị động tương lai đơn: will be + V3; có thể bỏ \"by people\".\nb) Bị động quá khứ đơn: was/were + V3 + by + tác nhân.\nc) Dự định đã có từ trước → \"be going to\".\nSai dạng động từ trừ toàn bộ điểm câu đó." },
  { id: "anh10-2-16", subject: "anh", grade: 10, chapter: "anh10-2", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Write a paragraph (about 100 words) suggesting some ways teenagers can live a greener lifestyle.", answer: "Đoạn văn khoảng 100 từ nêu 3–4 cách sống xanh cho thanh thiếu niên, có giải thích.", explanation: "Tiêu chí: câu chủ đề (2 điểm); ít nhất 3 ý có giải thích, dùng từ vựng chủ đề (eco-friendly, reduce, recycle, carbon footprint...) (4 điểm); câu kết (2 điểm); ngữ pháp, liên kết (2 điểm).\nBài mẫu: There are many simple ways teenagers can live a greener lifestyle. First, we can walk or cycle to school instead of asking our parents to drive us. This reduces our carbon footprint and keeps us fit. Second, we should say no to single-use plastic by carrying reusable bottles and cloth bags. Third, we can save energy by turning off lights, fans and computers when we do not use them. Finally, we can join eco-friendly activities such as planting trees or collecting rubbish in our neighbourhood. If every teenager makes these small changes, our environment will be cleaner and healthier." },
  { id: "anh10-3-01", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the word whose part in brackets is pronounced differently from the others. (Chọn từ có phần trong ngoặc [ ] phát âm khác)", options: ["j[u]dge","m[u]sic","f[u]n","dr[u]m"], answer: 1, explanation: "\"music\" có \"u\" đọc /juː/; các từ còn lại đọc /ʌ/." },
  { id: "anh10-3-02", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThe ___ gave her full marks for her amazing performance in the singing contest.", options: ["judges","audiences","contestants","fans"], answer: 0, explanation: "judges = ban giám khảo, những người chấm điểm." },
  { id: "anh10-3-03", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nMy brother loves music, ___ he can't play any musical instruments.", options: ["so","or","and","but"], answer: 3, explanation: "Hai ý tương phản (yêu âm nhạc nhưng không chơi được nhạc cụ) → \"but\"." },
  { id: "anh10-3-04", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Speaking & Communication", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Choose the most suitable response to complete the exchange.\nA: \"Would you like to go to the music festival with me this Saturday?\"\nB: \"___\"", options: ["I'd love to. What time does it start?","Yes, I like music very much.","It's very interesting.","No, I don't."], answer: 0, explanation: "Đáp lại lời mời \"Would you like to...?\": \"I'd love to.\" là cách nhận lời phù hợp." },
  { id: "anh10-3-05", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nTraditional music is an important part of Vietnamese culture. Recently, many young people have become more interested ___ folk songs such as quan ho and ca tru, thanks to modern versions on social media.", options: ["on","in","at","with"], answer: 1, explanation: "Cụm \"be/become interested in\" = quan tâm, hứng thú với." },
  { id: "anh10-3-06", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Reading", type: "tf", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nLast month, seventeen-year-old Hoang Anh won a national TV talent show. She comes from a small village in Nghe An, where she started singing folk songs with her grandmother. In the final round, she performed a modern version of a traditional song, and the audience gave her a standing ovation. The judges praised her powerful voice and her confidence on stage. Hoang Anh says she will use part of the prize money to build a small music room for the children in her village. She hopes to release her first album next year.", statements: ["Hoang Anh learnt folk songs from her grandmother.","She sang a pop song in the final round.","The judges liked her voice and her confidence.","Her first album has already been released."], answer: [true,false,true,false], explanation: "a) Đúng. b) Sai: cô hát phiên bản hiện đại của một bài hát truyền thống. c) Đúng. d) Sai: cô hy vọng phát hành album vào năm sau." },
  { id: "anh10-3-07", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the word that differs from the other three in the position of the main stress. (Chọn từ có trọng âm chính khác)", options: ["perform","concert","talent","music"], answer: 0, explanation: "perform /pəˈfɔːm/ nhấn âm 2; concert, talent, music nhấn âm 1." },
  { id: "anh10-3-08", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nShe can play three musical ___: the piano, the guitar and the violin.", options: ["equipment","tools","instruments","devices"], answer: 2, explanation: "\"musical instruments\" = nhạc cụ." },
  { id: "anh10-3-09", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Vocabulary", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThe band's new album will be ___ next month, and fans are very excited.", options: ["released","relieved","replaced","reached"], answer: 0, explanation: "\"release an album\" = phát hành album." },
  { id: "anh10-3-10", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nShe decided ___ part in the school singing contest.", options: ["taking","to take","take","took"], answer: 1, explanation: "\"decide + to V\" → to take." },
  { id: "anh10-3-11", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Grammar", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nI really enjoy ___ to pop music in my free time.", options: ["to listen","listening","listen","listened"], answer: 1, explanation: "\"enjoy + V-ing\" → listening." },
  { id: "anh10-3-12", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Grammar", type: "mcq", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Choose the part of the sentence that contains a mistake and needs correcting. (Tìm lỗi sai)\nThe audience kept to cheer after the band finished performing.", options: ["after","finished","performing","kept to cheer"], answer: 3, explanation: "\"keep + V-ing\" → sửa \"kept to cheer\" thành \"kept cheering\". \"finish + V-ing\" (performing) là đúng." },
  { id: "anh10-3-13", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nMany famous singers started their careers ___ taking part in TV talent shows. These shows give young people a chance to show their talent to millions of viewers.", options: ["with","by","of","for"], answer: 1, explanation: "\"by + V-ing\" diễn tả cách thức: bằng cách tham gia các chương trình tài năng." },
  { id: "anh10-3-14", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Reading", type: "tf", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nMany studies show that learning music is good for students. When students learn to play an instrument, they must read notes, count beats and use both hands at the same time. This trains their memory and concentration. Playing in a school band also teaches teamwork, because every member has to listen to the others. However, some parents worry that music lessons take time away from schoolwork. Researchers say that this is rarely a problem: students who study music often manage their time better and get similar or even higher marks in other subjects.", statements: ["Playing an instrument can improve memory and concentration.","Being in a band teaches students to work alone.","Some parents are concerned about the time music lessons take.","Researchers found that music students usually get lower marks."], answer: [true,false,true,false], explanation: "a) Đúng: \"This trains their memory and concentration.\" b) Sai: ban nhạc dạy tinh thần đồng đội. c) Đúng: một số phụ huynh lo ngại. d) Sai: điểm tương đương hoặc cao hơn." },
  { id: "anh10-3-15", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Rewrite each sentence so that its meaning stays the same, using the word(s) given in brackets.\na) He wants to win the contest. He practises the guitar every day. (so)\nb) I don't enjoy rock music. I like pop music. (but)\nc) It is fun to sing karaoke with friends. (Singing)", answer: "a) He wants to win the contest, so he practises the guitar every day. b) I don't enjoy rock music, but I like pop music. c) Singing karaoke with friends is fun.", explanation: "Mỗi câu 1/3 số điểm.\na) \"so\" nối mệnh đề chỉ kết quả; nguyên nhân đứng trước.\nb) \"but\" nối hai ý tương phản (câu ghép, có dấu phẩy).\nc) Danh động từ (V-ing) làm chủ ngữ, động từ chia số ít \"is\".\nĐặt \"so\" sai vị trí (đảo nguyên nhân – kết quả) không cho điểm câu a." },
  { id: "anh10-3-16", subject: "anh", grade: 10, chapter: "anh10-3", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Write a paragraph (about 100 words) about your favourite kind of music. Say what it is, when you listen to it and why you like it.", answer: "Đoạn văn khoảng 100 từ về thể loại nhạc yêu thích: là gì, nghe khi nào, vì sao thích.", explanation: "Tiêu chí: câu chủ đề (2 điểm); trả lời đủ 3 ý, dùng từ vựng chủ đề (lyrics, melody, perform, release, concert...) (4 điểm); câu kết (2 điểm); ngữ pháp, liên kết (2 điểm).\nBài mẫu: My favourite kind of music is acoustic pop. I usually listen to it in the evening while I am doing my homework or before I go to bed. I like it for several reasons. First, the melodies are gentle and help me relax after a long day at school. Second, the lyrics are often about friendship and family, so they are easy to understand and very meaningful. Third, acoustic songs make me want to learn the guitar, and I have started taking lessons. I hope that one day I can perform my favourite songs at a school concert." },
  { id: "anh10-4-01", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the word whose part in brackets is pronounced differently from the others. (Chọn từ có phần trong ngoặc [ ] phát âm khác)", options: ["donat[ed]","collect[ed]","need[ed]","help[ed]"], answer: 3, explanation: "\"helped\" có đuôi -ed đọc /t/ (sau âm /p/); các từ còn lại đọc /ɪd/ (sau /t/, /d/)." },
  { id: "anh10-4-02", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nLast month our class ___ old clothes and books to children in remote areas.", options: ["borrowed","donated","earned","received"], answer: 1, explanation: "donate = quyên góp, hợp với \"to children in remote areas\"." },
  { id: "anh10-4-03", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nLast summer, we ___ more than 200 trees in our neighbourhood.", options: ["plant","planted","have planted","plants"], answer: 1, explanation: "\"Last summer\" là thời gian xác định trong quá khứ → quá khứ đơn \"planted\"." },
  { id: "anh10-4-04", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Speaking & Communication", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Choose the most suitable response to complete the exchange.\nA: \"Thank you so much for helping us at the food bank today.\"\nB: \"___\"", options: ["It was my pleasure.","Yes, please.","I'm sorry to hear that.","Good idea!"], answer: 0, explanation: "Đáp lại lời cảm ơn: \"It was my pleasure.\" (Rất vui được giúp)." },
  { id: "anh10-4-05", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nYoung people can help their community ___ many ways, such as teaching poor children, cleaning streets or visiting elderly people living alone.", options: ["on","in","by","at"], answer: 1, explanation: "Cụm cố định \"in many ways\" = bằng nhiều cách." },
  { id: "anh10-4-06", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Reading", type: "tf", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nThe Sunshine Volunteer Club was started by a group of students in Hue three years ago. Every Saturday morning, members visit a centre for disadvantaged children, where they teach English and maths and play games with the kids. Last December, the club organised a fund-raising fair and raised over 30 million dong. They used the money to buy warm clothes and school bags for children in a mountainous area. Many members say that volunteering has made them more patient and grateful for what they have.", statements: ["The club was set up three years ago.","Members visit the centre on Sunday afternoons.","The money from the fair was spent on clothes and school bags.","According to the members, volunteering has made them less patient."], answer: [true,false,true,false], explanation: "a) Đúng. b) Sai: sáng thứ Bảy. c) Đúng. d) Sai: họ trở nên kiên nhẫn hơn (more patient)." },
  { id: "anh10-4-07", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the word that differs from the other three in the position of the main stress. (Chọn từ có trọng âm chính khác)", options: ["charity","benefit","generous","volunteer"], answer: 3, explanation: "volunteer /ˌvɒlənˈtɪə/ nhấn âm 3; charity, benefit, generous nhấn âm 1." },
  { id: "anh10-4-08", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nShe works as a ___ at the local hospital; she helps patients but doesn't get paid.", options: ["manager","employee","volunteer","patient"], answer: 2, explanation: "volunteer = tình nguyện viên, làm việc không lương." },
  { id: "anh10-4-09", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Vocabulary", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nVolunteer work can ___ both the community and the volunteers themselves.", options: ["beneficial","benefit","beneficially","beneficiary"], answer: 1, explanation: "Sau động từ khuyết thiếu \"can\" cần động từ nguyên mẫu → benefit (mang lại lợi ích)." },
  { id: "anh10-4-10", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nWhile I ___ an old man across the street, my phone rang.", options: ["helped","help","am helping","was helping"], answer: 3, explanation: "Hành động đang diễn ra (\"While...\") thì hành động khác xen vào → quá khứ tiếp diễn \"was helping\"." },
  { id: "anh10-4-11", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Grammar", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThey were cleaning the beach when it suddenly ___ to rain.", options: ["started","was starting","starts","has started"], answer: 0, explanation: "Hành động xen vào (ngắn, bất ngờ) dùng quá khứ đơn sau \"when\" → started." },
  { id: "anh10-4-12", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Grammar", type: "mcq", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nA: \"What ___ at 8 p.m. yesterday?\"\nB: \"I was preparing gifts for the charity event.\"", options: ["did you do","do you do","are you doing","were you doing"], answer: 3, explanation: "Hỏi về hành động đang diễn ra tại thời điểm xác định trong quá khứ → quá khứ tiếp diễn \"were you doing\"; câu trả lời cũng dùng quá khứ tiếp diễn." },
  { id: "anh10-4-13", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nLast year our school held a charity concert. The money ___ from the concert was used to build a small library for a village school.", options: ["risen","rose","raising","raised"], answer: 3, explanation: "\"raise money\" = quyên tiền; rút gọn mệnh đề bị động \"which was raised\" → raised." },
  { id: "anh10-4-14", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Reading", type: "tf", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nWhen Nam first joined a group that cooks free meals for patients' families at a city hospital, he only wanted to fill his free time during the summer holiday. He had to get up at five o'clock, chop vegetables and wash huge pots. On the third day, an old woman held his hand and told him that his meal was the first hot food she had eaten in a week. From that moment, Nam saw the work differently. He stayed with the group for the whole summer and later persuaded two classmates to join. Now he is planning to study social work at university.", statements: ["Nam's original reason for volunteering was to use his free time.","The work in the kitchen was easy and started late in the morning.","A conversation with an old woman changed Nam's attitude.","Nam left the group after the first week."], answer: [true,false,true,false], explanation: "a) Đúng: ban đầu chỉ muốn lấp thời gian rảnh. b) Sai: phải dậy lúc 5 giờ, công việc vất vả. c) Đúng: suy luận từ \"From that moment, Nam saw the work differently\". d) Sai: cậu ở lại cả mùa hè." },
  { id: "anh10-4-15", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Rewrite each sentence so that its meaning stays the same, using the word(s) given in brackets.\na) I was walking home. I saw a fire in an old house. (While)\nb) He started volunteering at the animal shelter two years ago. (for)\nc) Collecting rubbish on the beach was very tiring. (It)", answer: "a) While I was walking home, I saw a fire in an old house. b) He has volunteered (has been volunteering) at the animal shelter for two years. c) It was very tiring to collect rubbish on the beach.", explanation: "Mỗi câu 1/3 số điểm.\na) \"While + quá khứ tiếp diễn\", mệnh đề chính quá khứ đơn.\nb) Quá khứ đơn + \"ago\" → hiện tại hoàn thành + \"for\".\nc) Cấu trúc \"It + be + adj + to V\" thay cho chủ ngữ V-ing." },
  { id: "anh10-4-16", subject: "anh", grade: 10, chapter: "anh10-4", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Write a paragraph (about 100 words) about a volunteer activity you would like to join. Say what it is, who it helps and why you want to do it.", answer: "Đoạn văn khoảng 100 từ: hoạt động tình nguyện, đối tượng được giúp, lý do.", explanation: "Tiêu chí: câu chủ đề (2 điểm); đủ 3 ý, dùng từ vựng chủ đề (volunteer, donate, disadvantaged, community, benefit...) (4 điểm); câu kết (2 điểm); ngữ pháp, liên kết (2 điểm).\nBài mẫu: I would like to join a volunteer programme that teaches English to disadvantaged children in my town. Many of these children cannot afford extra classes, so they find it hard to keep up with their classmates. As a volunteer, I could help them with vocabulary and simple conversations twice a week. I want to do this for several reasons. First, I love English and enjoy sharing what I know. Second, I believe education can change a child's future. Finally, volunteering would help me become more patient and confident. I think this activity would benefit both the children and me." },
  { id: "anh10-5-01", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the word whose part in brackets is pronounced differently from the others. (Chọn từ có phần trong ngoặc [ ] phát âm khác)", options: ["devi[c]e","pri[c]e","[c]amera","[c]ity"], answer: 2, explanation: "\"camera\" có \"c\" đọc /k/; các từ còn lại \"c\" đọc /s/." },
  { id: "anh10-5-02", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nA laptop is ___, so you can carry it anywhere easily.", options: ["heavy","expensive","portable","fixed"], answer: 2, explanation: "portable = có thể mang theo, xách tay; hợp với \"carry it anywhere\"." },
  { id: "anh10-5-03", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nScientists ___ many useful devices so far.", options: ["have invented","invented","invent","are inventing"], answer: 0, explanation: "\"so far\" là dấu hiệu của thì hiện tại hoàn thành → have invented." },
  { id: "anh10-5-04", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Speaking & Communication", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Choose the most suitable response to complete the exchange.\nA: \"What do you think of this new electric toothbrush?\"\nB: \"___\"", options: ["I think it's really useful and easy to use.","It's mine.","Yes, I do.","I bought it yesterday."], answer: 0, explanation: "Câu hỏi xin ý kiến \"What do you think of...?\" → trả lời bằng nhận xét: \"I think it's really useful...\"" },
  { id: "anh10-5-05", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nSmartphones are amazing inventions. Today they are used ___ taking photos, sending messages, paying bills and even learning languages.", options: ["to","with","by","for"], answer: 3, explanation: "\"be used for + V-ing\" = được dùng để làm gì (nói về công dụng)." },
  { id: "anh10-5-06", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Reading", type: "tf", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nThe light bulb is one of the most important inventions in history. Before it was invented, people used candles and oil lamps, which were dim and could cause fires. Many inventors tried to make electric light, but Thomas Edison is famous for producing a practical and long-lasting bulb in 1879. Today, traditional bulbs have mostly been replaced by LED lights, which use much less electricity and last for many years. Thanks to this invention, people can work, study and travel safely after dark.", statements: ["Before electric light, people used candles and oil lamps.","Edison was the only person who tried to make electric light.","LED lights use less electricity than traditional bulbs.","According to the passage, LED lights only last for a few months."], answer: [true,false,true,false], explanation: "a) Đúng. b) Sai: \"Many inventors tried to make electric light\". c) Đúng. d) Sai: đèn LED dùng được nhiều năm." },
  { id: "anh10-5-07", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the word that differs from the other three in the position of the main stress. (Chọn từ có trọng âm chính khác)", options: ["invention","computer","popular","technology"], answer: 2, explanation: "popular /ˈpɒpjələ/ nhấn âm 1; invention, computer, technology nhấn âm 2." },
  { id: "anh10-5-08", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThomas Edison was a famous ___ who gave us a practical electric light bulb.", options: ["invention","invent","inventor","inventive"], answer: 2, explanation: "Cần danh từ chỉ người sau \"a famous\" và trước \"who\" → inventor (nhà phát minh)." },
  { id: "anh10-5-09", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Vocabulary", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nSmartphones have completely ___ the way people communicate with each other.", options: ["transformed","transported","transferred","translated"], answer: 0, explanation: "transform = thay đổi hoàn toàn; \"transform the way...\" hợp nghĩa." },
  { id: "anh10-5-10", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nA robot vacuum cleaner is used for ___ floors.", options: ["clean","to clean","cleaned","cleaning"], answer: 3, explanation: "Sau giới từ \"for\" dùng V-ing → cleaning." },
  { id: "anh10-5-11", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Grammar", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nI ___ this laptop since I started secondary school.", options: ["used","have used","use","am using"], answer: 1, explanation: "\"since + mốc thời gian\" → hiện tại hoàn thành \"have used\"." },
  { id: "anh10-5-12", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Grammar", type: "mcq", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThis is the first time I ___ a 3D printer in real life.", options: ["saw","see","have seen","had seen"], answer: 2, explanation: "Cấu trúc \"This is the first time + S + have/has + V3\" → have seen." },
  { id: "anh10-5-13", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nThe first electronic computers were as big as a room. Since then, computers ___ much smaller, faster and cheaper, and now many people carry one in their pocket.", options: ["have become","became","become","are becoming"], answer: 0, explanation: "\"Since then\" (từ đó đến nay) → hiện tại hoàn thành \"have become\"." },
  { id: "anh10-5-14", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Reading", type: "tf", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nFifteen-year-old Quang from Can Tho noticed that his grandmother often forgot to take her medicine. So he invented a small pill box that beeps and flashes at the right time each day. If the box is not opened within ten minutes, it sends a text message to a family member's phone. Quang built the first model with cheap parts and taught himself basic programming online. His invention won second prize at a national science fair, and a local company has offered to help him produce it. Quang says the best reward is that his grandmother has not missed a single dose since she started using it.", statements: ["Quang's invention was inspired by a family member's problem.","The pill box calls a doctor if it is not opened.","Quang learnt programming without going to a special school.","Quang thinks winning the prize is more important than helping his grandmother."], answer: [true,false,true,false], explanation: "a) Đúng: ý tưởng xuất phát từ việc bà hay quên uống thuốc. b) Sai: hộp gửi tin nhắn cho người nhà, không gọi bác sĩ. c) Đúng: \"taught himself basic programming online\". d) Sai: phần thưởng lớn nhất với Quang là bà không quên liều thuốc nào." },
  { id: "anh10-5-15", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Rewrite each sentence so that its meaning stays the same, using the word(s) given in brackets.\na) I last used a typewriter ten years ago. (haven't)\nb) This is the most useful invention I have ever seen. (never)\nc) People use 3D printers to make models. (are)", answer: "a) I haven't used a typewriter for ten years. b) I have never seen a more useful invention than this (one). c) 3D printers are used to make models / for making models.", explanation: "Mỗi câu 1/3 số điểm.\na) \"last + V2 + ago\" → \"haven't + V3 + for\".\nb) So sánh nhất + \"ever\" ↔ \"never ... + so sánh hơn + than\".\nc) Câu bị động hiện tại đơn; nói công dụng dùng \"be used to V\" hoặc \"be used for V-ing\"." },
  { id: "anh10-5-16", subject: "anh", grade: 10, chapter: "anh10-5", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Write a paragraph (about 100 words) about an invention you find most useful in your daily life. Describe what it is, how you use it and why it is important to you.", answer: "Đoạn văn khoảng 100 từ về một phát minh hữu ích: là gì, dùng ra sao, tầm quan trọng.", explanation: "Tiêu chí: câu chủ đề (2 điểm); đủ 3 ý, dùng cấu trúc \"be used for V-ing / to V\" và từ vựng chủ đề (device, portable, invention...) (4 điểm); câu kết (2 điểm); ngữ pháp, liên kết (2 điểm).\nBài mẫu: In my opinion, the most useful invention in my daily life is the smartphone. It is a small, portable device, but it can do many things. I use it for keeping in touch with my family and friends, checking my timetable and looking up new English words. It is also used to take photos and listen to music on the way to school. The smartphone is important to me because it saves time and helps me learn anywhere. However, I try not to use it too much so that it does not affect my health. I cannot imagine my life without it." },
  { id: "anh10-6-01", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the word whose part in brackets is pronounced differently from the others. (Chọn từ có phần trong ngoặc [ ] phát âm khác)", options: ["w[or]k","f[ar]mer","n[ur]se","s[ur]geon"], answer: 1, explanation: "\"farmer\" có \"ar\" đọc /ɑː/; \"work, nurse, surgeon\" đọc /ɜː/." },
  { id: "anh10-6-02", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nGender ___ means that men and women have the same rights and opportunities.", options: ["equal","equally","equality","equalise"], answer: 2, explanation: "Sau \"Gender\" cần danh từ → equality (sự bình đẳng)." },
  { id: "anh10-6-03", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nBoys and girls should ___ equally at school.", options: ["treat","treated","be treating","be treated"], answer: 3, explanation: "Chủ ngữ chịu tác động → bị động với động từ khuyết thiếu: should + be + V3." },
  { id: "anh10-6-04", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Speaking & Communication", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Choose the most suitable response to complete the exchange.\nA: \"I think women can be excellent airline pilots.\"\nB: \"___\"", options: ["You're welcome.","Never mind.","I couldn't agree more.","That's all right."], answer: 2, explanation: "\"I couldn't agree more\" = Tôi hoàn toàn đồng ý; phù hợp để đáp lại một ý kiến." },
  { id: "anh10-6-05", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nIn the past, many girls in poor rural areas did not have the ___ to go to school because they had to help with housework or get married early.", options: ["ambition","decision","attention","opportunity"], answer: 3, explanation: "\"have the opportunity to do sth\" = có cơ hội làm gì." },
  { id: "anh10-6-06", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Reading", type: "tf", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nDr Mai is one of the few female heart surgeons in her province. When she told her family she wanted to study medicine, some relatives said surgery was \"a job for men\" because it requires long hours and great physical strength. Mai ignored these comments and graduated at the top of her class. Today she leads a team of ten doctors, most of whom are men. She often visits schools to talk to students and encourages girls to choose careers in science and medicine. \"Your ability, not your gender, should decide your future,\" she tells them.", statements: ["Some of Mai's relatives did not support her career choice at first.","Mai finished her studies with poor results.","Most of the doctors in her team are women.","Mai encourages girls to work in science and medicine."], answer: [true,false,false,true], explanation: "a) Đúng: một số họ hàng cho rằng phẫu thuật là \"việc của đàn ông\". b) Sai: cô tốt nghiệp thủ khoa. c) Sai: phần lớn là nam. d) Đúng." },
  { id: "anh10-6-07", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the word that differs from the other three in the position of the main stress. (Chọn từ có trọng âm chính khác)", options: ["equal","pilot","career","female"], answer: 2, explanation: "career /kəˈrɪə/ nhấn âm 2; equal, pilot, female nhấn âm 1." },
  { id: "anh10-6-08", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nNo one should suffer from ___ at work just because of their gender.", options: ["development","discrimination","decoration","description"], answer: 1, explanation: "discrimination = sự phân biệt đối xử." },
  { id: "anh10-6-09", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Vocabulary", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nParents should ___ their daughters to follow careers in science and technology.", options: ["encourage","discourage","prevent","stop"], answer: 0, explanation: "\"encourage sb to do sth\" = khuyến khích ai làm gì; hợp nghĩa câu." },
  { id: "anh10-6-10", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nHousework must ___ by all members of the family.", options: ["be shared","share","shared","sharing"], answer: 0, explanation: "Bị động với động từ khuyết thiếu: must + be + V3 → must be shared." },
  { id: "anh10-6-11", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Grammar", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nMore women ___ to take leadership roles in the future.", options: ["will encourage","are encouraging","encourage","will be encouraged"], answer: 3, explanation: "Phụ nữ \"được khuyến khích\" (bị động) trong tương lai → will be encouraged." },
  { id: "anh10-6-12", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Grammar", type: "mcq", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nEqual pay for equal work ___ to all employees, regardless of their gender.", options: ["should give","should be giving","should be given","should have given"], answer: 2, explanation: "\"Equal pay\" là đối tượng được trao → bị động \"should be given\"." },
  { id: "anh10-6-13", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nToday, women are successfully working in many jobs ___ used to be done only by men, such as engineers, pilots and firefighters.", options: ["that","who","what","where"], answer: 0, explanation: "Đại từ quan hệ thay cho \"jobs\" (vật), làm chủ ngữ → that (hoặc which)." },
  { id: "anh10-6-14", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Reading", type: "tf", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nFor many years, female athletes received much less prize money than male athletes, even when they won the same competitions. In tennis, this began to change in the 1970s, when top women players demanded equal pay. Since 2007, all four Grand Slam tournaments have paid men and women the same prize money. However, in many other sports the gap remains large, and women's games still get less TV time and fewer sponsors. Supporters of equality argue that if women's sports are shown more often, more fans will watch them and more money will follow.", statements: ["Female athletes have always received the same prize money as men.","Women tennis players played a role in changing the pay rules.","The pay gap has disappeared in all sports.","Supporters believe more media coverage could bring more money to women's sports."], answer: [false,true,false,true], explanation: "a) Sai: trong nhiều năm nữ nhận ít tiền thưởng hơn. b) Đúng: các tay vợt nữ hàng đầu đòi trả lương bằng nhau. c) Sai: khoảng cách vẫn lớn ở nhiều môn khác. d) Đúng: suy ra từ câu cuối." },
  { id: "anh10-6-15", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Rewrite each sentence so that its meaning stays the same, using the word(s) given in brackets.\na) We must give boys and girls the same chances. (given)\nb) Schools should teach students about gender equality. (taught)\nc) People can't judge a person's ability by his or her gender. (judged)", answer: "a) Boys and girls must be given the same chances. b) Students should be taught about gender equality (by schools). c) A person's ability can't be judged by his or her gender.", explanation: "Mỗi câu 1/3 số điểm.\nCông thức bị động với động từ khuyết thiếu: S + modal + be + V3 (+ by O).\nCó thể bỏ tác nhân không xác định (we, people). Thiếu \"be\" hoặc sai V3 không cho điểm câu đó." },
  { id: "anh10-6-16", subject: "anh", grade: 10, chapter: "anh10-6", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Write a paragraph (about 100 words) giving your opinion: Should men and women share housework equally?", answer: "Đoạn văn khoảng 100 từ nêu quan điểm về việc nam và nữ chia sẻ việc nhà bình đẳng, có lý do.", explanation: "Tiêu chí: nêu rõ quan điểm (2 điểm); ít nhất 2–3 lý do có giải thích, dùng từ vựng chủ đề (equal, share, gender, opportunity...) (4 điểm); câu kết khẳng định lại quan điểm (2 điểm); ngữ pháp, liên kết (2 điểm).\nBài mẫu: In my opinion, men and women should share housework equally. Firstly, in most families today both husbands and wives go to work, so it is unfair if only women have to cook and clean after a long day. Secondly, sharing chores gives women more time to rest, study or develop their careers. Thirdly, when children see their fathers doing housework, they learn that household tasks are not \"women's jobs\". This helps to build gender equality for the next generation. Therefore, I believe housework should be shared by all family members, not just by women." },
  { id: "anh10-7-01", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the word whose part in brackets is pronounced differently from the others. (Chọn từ có phần trong ngoặc [ ] phát âm khác)", options: ["organisa[t]ion","na[t]ion","educa[t]ion","ques[t]ion"], answer: 3, explanation: "\"question\" có \"t\" đọc /tʃ/; trong \"-tion\" của các từ còn lại \"t\" đọc /ʃ/." },
  { id: "anh10-7-02", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nViet Nam became a ___ of the United Nations in 1977.", options: ["leader","founder","member","visitor"], answer: 2, explanation: "\"become a member of\" = trở thành thành viên của; Việt Nam gia nhập Liên Hợp Quốc năm 1977." },
  { id: "anh10-7-03", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nHo Chi Minh City is ___ than Ha Noi in terms of population.", options: ["largest","larger","more large","the larger"], answer: 1, explanation: "Có \"than\" → so sánh hơn của tính từ ngắn: large → larger." },
  { id: "anh10-7-04", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Speaking & Communication", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Choose the most suitable response to complete the exchange.\nA: \"What do you think about Viet Nam joining UN peacekeeping operations?\"\nB: \"___\"", options: ["Yes, I joined it last year.","It's my pleasure.","I don't know where it is.","In my opinion, it shows our country's commitment to world peace."], answer: 3, explanation: "Câu hỏi xin ý kiến → trả lời bằng quan điểm \"In my opinion, ...\"." },
  { id: "anh10-7-05", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nUNICEF is a United Nations organisation that works for children. In Viet Nam, it provides children in poor areas ___ clean water, healthcare and education.", options: ["for","to","of","with"], answer: 3, explanation: "Cấu trúc \"provide sb with sth\" = cung cấp cho ai cái gì." },
  { id: "anh10-7-06", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Reading", type: "tf", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nViet Nam joined the United Nations in 1977. Since then, the country has worked closely with many UN agencies, such as UNICEF, UNDP and WHO, to improve education, healthcare and living standards. Viet Nam has also taken a more active role in international affairs. It was elected a non-permanent member of the UN Security Council twice, for 2008–2009 and 2020–2021. Since 2014, Vietnamese officers have taken part in UN peacekeeping missions, and in 2018 Viet Nam sent its first field hospital to South Sudan.", statements: ["Viet Nam has been a UN member since 1977.","Viet Nam has been a non-permanent member of the Security Council only once.","Vietnamese officers started joining UN peacekeeping missions in 2014.","Viet Nam's first field hospital was sent to Africa before 2014."], answer: [true,false,true,false], explanation: "a) Đúng. b) Sai: hai lần (2008–2009 và 2020–2021). c) Đúng. d) Sai: bệnh viện dã chiến đầu tiên được cử đi năm 2018." },
  { id: "anh10-7-07", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the word that differs from the other three in the position of the main stress. (Chọn từ có trọng âm chính khác)", options: ["agreement","commitment","poverty","contribute"], answer: 2, explanation: "poverty /ˈpɒvəti/ nhấn âm 1; agreement, commitment, contribute nhấn âm 2." },
  { id: "anh10-7-08", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nUNICEF works to protect the rights of ___ all over the world.", options: ["soldiers","children","companies","tourists"], answer: 1, explanation: "UNICEF là Quỹ Nhi đồng Liên Hợp Quốc, bảo vệ quyền trẻ em." },
  { id: "anh10-7-09", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Vocabulary", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nJoining the WTO in 2007 helped Viet Nam ___ its exports and economic growth.", options: ["boost","reduce","prevent","remove"], answer: 0, explanation: "boost = thúc đẩy, làm tăng; hợp nghĩa \"helped Viet Nam ... economic growth\"." },
  { id: "anh10-7-10", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThe United Nations is one of ___ international organisations in the world.", options: ["the largest","larger","the most large","largest"], answer: 0, explanation: "\"one of + the + so sánh nhất + danh từ số nhiều\" → the largest." },
  { id: "anh10-7-11", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Grammar", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nUN peacekeeping missions are becoming ___ important for world peace.", options: ["more and more","most and most","the more","much more and"], answer: 0, explanation: "So sánh lũy tiến với tính từ dài: more and more + adj." },
  { id: "anh10-7-12", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Grammar", type: "mcq", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThe more countries join the organisation, ___ its influence becomes.", options: ["the stronger","stronger","the strongest","more strong"], answer: 0, explanation: "So sánh kép: \"The + so sánh hơn ..., the + so sánh hơn ...\" → the stronger." },
  { id: "anh10-7-13", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nOver the past decades, Viet Nam has received a lot of ___ from international organisations to reduce poverty and improve people's lives.", options: ["supportive","supporter","support","supported"], answer: 2, explanation: "Sau \"a lot of\" cần danh từ; nghĩa \"sự hỗ trợ\" → support." },
  { id: "anh10-7-14", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Reading", type: "tf", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nOn 11 January 2007, Viet Nam officially became the 150th member of the World Trade Organization (WTO). To join, the country had to negotiate for more than ten years and change many of its laws. Membership opened up larger markets for Vietnamese products such as rice, coffee, seafood and clothes. Foreign companies also invested more in the country, creating millions of jobs. However, joining the WTO brought challenges too. Local businesses had to compete with stronger foreign companies, and farmers had to meet stricter quality standards to sell their products abroad.", statements: ["Viet Nam joined the WTO quickly, without having to change its laws.","Membership helped Vietnamese goods reach more markets.","According to the passage, WTO membership brought only advantages.","After joining, some Vietnamese farmers had to improve the quality of their products."], answer: [false,true,false,true], explanation: "a) Sai: đàm phán hơn 10 năm và phải sửa đổi nhiều luật. b) Đúng. c) Sai: đoạn văn nêu cả thách thức. d) Đúng: suy ra từ \"had to meet stricter quality standards\"." },
  { id: "anh10-7-15", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Rewrite each sentence so that its meaning stays the same, using the word(s) given in brackets.\na) No organisation in the world is bigger than the UN. (biggest)\nb) This project is less expensive than that one. (more)\nc) As Viet Nam's economy grows, people's lives get better. (The more)", answer: "a) The UN is the biggest organisation in the world. b) That project is more expensive than this one. c) The more Viet Nam's economy grows, the better people's lives get.", explanation: "Mỗi câu 1/3 số điểm.\na) Phủ định + so sánh hơn ↔ so sánh nhất.\nb) \"less + adj + than\" ↔ đảo hai đối tượng với \"more + adj + than\".\nc) So sánh kép \"The more ..., the better ...\". Thiếu \"the\" ở vế sau trừ một nửa điểm câu c." },
  { id: "anh10-7-16", subject: "anh", grade: 10, chapter: "anh10-7", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Write a paragraph (about 100 words) about the benefits Viet Nam has gained from joining an international organisation (e.g. the UN, UNICEF, the WTO or ASEAN).", answer: "Đoạn văn khoảng 100 từ nêu lợi ích Việt Nam nhận được khi tham gia một tổ chức quốc tế.", explanation: "Tiêu chí: câu chủ đề nêu tên tổ chức (2 điểm); ít nhất 2–3 lợi ích có ví dụ, dùng từ vựng chủ đề (member, economic growth, poverty, support, promote...) (4 điểm); câu kết (2 điểm); ngữ pháp, liên kết (2 điểm). Thông tin sự kiện phải chính xác.\nBài mẫu: Joining the World Trade Organization in 2007 has brought Viet Nam many benefits. First, it has helped Vietnamese products such as rice, coffee and clothes reach larger markets around the world. As a result, our exports have grown quickly. Second, more foreign companies have invested in Viet Nam, which has created millions of jobs and helped reduce poverty. Third, to meet international standards, Vietnamese businesses have had to improve the quality of their goods and services. Although there are still challenges, I believe WTO membership has made Viet Nam's economy stronger and more modern." },
  { id: "anh10-8-01", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the word whose part in brackets is pronounced differently from the others. (Chọn từ có phần trong ngoặc [ ] phát âm khác)", options: ["d[i]gital","onl[i]ne","l[i]sten","[i]nteract"], answer: 1, explanation: "\"online\" có \"i\" đọc /aɪ/; các từ còn lại đọc /ɪ/." },
  { id: "anh10-8-02", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nIn ___ learning, students study both online and in the classroom.", options: ["blended","private","single","native"], answer: 0, explanation: "blended learning = học kết hợp (trực tuyến và trực tiếp)." },
  { id: "anh10-8-03", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThe teacher ___ teaches us English online is very friendly.", options: ["which","who","whose","where"], answer: 1, explanation: "Thay cho danh từ chỉ người \"The teacher\", làm chủ ngữ → who." },
  { id: "anh10-8-04", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Speaking & Communication", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Choose the most suitable response to complete the exchange.\nA: \"I find it hard to focus during online lessons.\"\nB: \"___\"", options: ["Yes, it's easy.","Why don't you turn off notifications on your phone?","Congratulations!","I'm good at it."], answer: 1, explanation: "Người nói nêu khó khăn → đưa ra lời khuyên \"Why don't you...?\"." },
  { id: "anh10-8-05", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nOne advantage of online learning is flexibility. Students can watch recorded lessons again and study at their own ___, without feeling rushed.", options: ["place","race","face","pace"], answer: 3, explanation: "\"at one's own pace\" = theo tốc độ của riêng mình." },
  { id: "anh10-8-06", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Reading", type: "tf", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nLast year, Tran Phu High School introduced blended learning for grade 10 students. Students now attend classes at school four days a week and study online on the fifth day. During online days, they watch short video lessons, complete quizzes and join group discussions on the school's learning platform. Teachers check the quiz results to see which topics students find difficult and then review them in class. Most students say they like the new system, although some complain that they spend too much time in front of screens.", statements: ["Grade 10 students study online one day a week.","On online days, students only read textbooks.","Teachers use quiz results to decide what to review.","All students are completely satisfied with the system."], answer: [true,false,true,false], explanation: "a) Đúng: 4 ngày ở trường, ngày thứ 5 học trực tuyến. b) Sai: xem video, làm bài kiểm tra, thảo luận nhóm. c) Đúng. d) Sai: một số em phàn nàn về thời gian dùng màn hình." },
  { id: "anh10-8-07", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the word that differs from the other three in the position of the main stress. (Chọn từ có trọng âm chính khác)", options: ["distract","effective","discuss","focus"], answer: 3, explanation: "focus /ˈfəʊkəs/ nhấn âm 1; distract, effective, discuss nhấn âm 2." },
  { id: "anh10-8-08", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nUsing your phone for social media during class can be a big ___.", options: ["distraction","attraction","instruction","construction"], answer: 0, explanation: "distraction = điều gây xao nhãng." },
  { id: "anh10-8-09", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Vocabulary", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nOnline platforms allow students to ___ with teachers and classmates easily.", options: ["interaction","interactive","interactively","interact"], answer: 3, explanation: "Cấu trúc \"allow sb to V\" → cần động từ nguyên mẫu: interact (tương tác)." },
  { id: "anh10-8-10", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThis is the app ___ helps me learn ten new words every day.", options: ["who","whose","where","which"], answer: 3, explanation: "Thay cho danh từ chỉ vật \"the app\", làm chủ ngữ → which (hoặc that)." },
  { id: "anh10-8-11", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Grammar", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nLan, ___ laptop is broken, has to use her brother's computer for online lessons.", options: ["who","whose","which","that"], answer: 1, explanation: "Chỉ sở hữu (laptop của Lan) → whose." },
  { id: "anh10-8-12", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Grammar", type: "mcq", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nMy school, ___ was built in 1990, has just introduced blended learning.", options: ["that","which","who","where"], answer: 1, explanation: "Mệnh đề quan hệ không xác định (có dấu phẩy) thay cho vật → which; không dùng \"that\" sau dấu phẩy." },
  { id: "anh10-8-13", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nOnline learning is not suitable for everyone. Students ___ do not have a stable Internet connection may find it difficult to follow the lessons.", options: ["which","who","whose","whom"], answer: 1, explanation: "Thay cho \"Students\" (người), làm chủ ngữ của \"do not have\" → who." },
  { id: "anh10-8-14", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Reading", type: "tf", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nOnline learning has both benefits and drawbacks. On the one hand, students can access lessons anytime and anywhere, and they can replay difficult parts as many times as they need. Shy students may also feel more comfortable asking questions in a chat box than in front of the class. On the other hand, studying alone at home requires strong self-discipline. Without a teacher nearby, some students easily get distracted by games or social media. In addition, long hours in front of a screen can cause eye strain and backache. Many experts therefore believe that a mix of online and face-to-face learning is the best solution.", statements: ["The passage presents only the advantages of online learning.","Shy students might find it easier to ask questions online.","Self-discipline is not important when studying at home.","Experts mentioned in the passage support blended learning."], answer: [false,true,false,true], explanation: "a) Sai: đoạn văn nêu cả lợi ích lẫn hạn chế. b) Đúng. c) Sai: học ở nhà đòi hỏi tính kỷ luật cao. d) Đúng: \"a mix of online and face-to-face learning\" chính là học kết hợp." },
  { id: "anh10-8-15", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Rewrite each sentence so that its meaning stays the same, using the word(s) given in brackets.\na) I have a friend. His mother teaches English online. (whose)\nb) The laptop is very light. I bought it last week. (which/that)\nc) Mr Nam is our IT teacher. He set up the school's online platform. (who)", answer: "a) I have a friend whose mother teaches English online. b) The laptop (which/that) I bought last week is very light. c) Mr Nam, who set up the school's online platform, is our IT teacher.", explanation: "Mỗi câu 1/3 số điểm.\na) \"His\" chỉ sở hữu → whose.\nb) Mệnh đề quan hệ xác định bổ nghĩa \"The laptop\"; đại từ làm tân ngữ nên có thể lược bỏ; không lặp lại \"it\".\nc) \"Mr Nam\" là tên riêng → mệnh đề không xác định, có hai dấu phẩy, dùng \"who\" (không dùng \"that\")." },
  { id: "anh10-8-16", subject: "anh", grade: 10, chapter: "anh10-8", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Write a paragraph (about 100 words) about the advantages of online learning for high school students.", answer: "Đoạn văn khoảng 100 từ nêu các lợi ích của việc học trực tuyến.", explanation: "Tiêu chí: câu chủ đề (2 điểm); ít nhất 3 lợi ích có giải thích, dùng từ vựng chủ đề (flexible, platform, interact, at one's own pace...) (4 điểm); câu kết (2 điểm); ngữ pháp, liên kết (2 điểm).\nBài mẫu: Online learning offers high school students several advantages. Firstly, it is flexible. Students can study at any time and in any place, so they can organise their timetable better. Secondly, they can learn at their own pace by replaying video lessons until they understand difficult topics. Thirdly, online platforms provide many useful resources, such as interactive quizzes, e-books and educational videos, which make learning more interesting. Finally, students who are shy can interact with teachers more easily through chat boxes. For these reasons, I believe online learning is a useful way to support traditional lessons at school." },
  { id: "anh10-9-01", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the word whose part in brackets is pronounced differently from the others. (Chọn từ có phần trong ngoặc [ ] phát âm khác)", options: ["ear[th]","clo[th]ing","[th]reat","heal[th]"], answer: 1, explanation: "\"clothing\" có \"th\" đọc /ð/; các từ còn lại \"th\" đọc /θ/." },
  { id: "anh10-9-02", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nTigers are an ___ species; there are very few of them left in the wild.", options: ["endangering","dangerous","endangered","danger"], answer: 2, explanation: "\"endangered species\" = loài có nguy cơ tuyệt chủng." },
  { id: "anh10-9-03", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nShe said, \"I am worried about climate change.\"\n→ She said that she ___ about climate change.", options: ["were worried","worry","was worried","has worried"], answer: 2, explanation: "Câu tường thuật lùi thì: am → was; chủ ngữ \"she\" → was worried." },
  { id: "anh10-9-04", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Speaking & Communication", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Choose the most suitable response to complete the exchange.\nA: \"We should use public transport more to reduce air pollution.\"\nB: \"___\"", options: ["You're right. It's better for the environment.","No, thanks. I'm full.","That sounds terrible.","I'm sorry I'm late."], answer: 0, explanation: "Đáp lại một ý kiến bằng sự đồng tình có lý do: \"You're right. ...\"" },
  { id: "anh10-9-05", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nClimate change is one of the biggest ___ to our planet. It causes rising sea levels, extreme weather and the loss of many animal habitats.", options: ["threaten","threatening","threats","threatened"], answer: 2, explanation: "Sau \"one of the biggest\" cần danh từ số nhiều → threats (mối đe dọa)." },
  { id: "anh10-9-06", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Reading", type: "tf", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nDeforestation is a serious problem in many parts of the world. Every year, millions of hectares of forest are cut down to make space for farms, roads and buildings. When forests disappear, animals lose their habitats, and some species become endangered. Trees also absorb carbon dioxide, so cutting them down contributes to global warming. In Viet Nam, many communities are now working to plant new forests, especially mangrove forests along the coast, which protect villages from storms and provide homes for fish and birds.", statements: ["Forests are mainly cut down to protect animals.","Losing forests can make some species endangered.","Trees help reduce the amount of carbon dioxide in the air.","Mangrove forests make coastal villages more likely to be damaged by storms."], answer: [false,true,true,false], explanation: "a) Sai: rừng bị chặt để lấy đất làm nông trại, đường, nhà cửa. b) Đúng. c) Đúng: cây hấp thụ CO2. d) Sai: rừng ngập mặn bảo vệ làng khỏi bão." },
  { id: "anh10-9-07", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the word that differs from the other three in the position of the main stress. (Chọn từ có trọng âm chính khác)", options: ["pollution","endangered","habitat","environment"], answer: 2, explanation: "habitat /ˈhæbɪtæt/ nhấn âm 1; pollution, endangered, environment nhấn âm 2." },
  { id: "anh10-9-08", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nCutting down forests destroys the natural ___ of many wild animals.", options: ["habitats","habits","inhabitants","habitations"], answer: 0, explanation: "habitat = môi trường sống tự nhiên của động vật." },
  { id: "anh10-9-09", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Vocabulary", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nOur school organised a campaign to ___ awareness of plastic pollution.", options: ["rise","arise","raise","grow"], answer: 2, explanation: "Cụm \"raise awareness of\" = nâng cao nhận thức về; \"rise\" là nội động từ, không có tân ngữ." },
  { id: "anh10-9-10", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nTom said, \"I recycle all my plastic bottles.\"\n→ Tom said that he ___ all his plastic bottles.", options: ["recycle","had recycling","recycled","was recycle"], answer: 2, explanation: "Lùi thì: hiện tại đơn → quá khứ đơn: recycle → recycled." },
  { id: "anh10-9-11", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Grammar", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nThe teacher said, \"We will plant trees tomorrow.\"\n→ The teacher said that they would plant trees ___.", options: ["tomorrow","yesterday","the next day","the day before"], answer: 2, explanation: "Trong câu tường thuật, \"tomorrow\" đổi thành \"the next day\" (the following day)." },
  { id: "anh10-9-12", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Grammar", type: "mcq", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\n\"We have collected 50 kilos of rubbish,\" the volunteers said.\n→ The volunteers said that they ___ 50 kilos of rubbish.", options: ["had collected","have collected","would collect","were collecting"], answer: 0, explanation: "Lùi thì: hiện tại hoàn thành → quá khứ hoàn thành \"had collected\"." },
  { id: "anh10-9-13", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nScientists warn that if we do not take action now, many species of animals and plants will ___ extinct within the next few decades.", options: ["make","turn into","bring","become"], answer: 3, explanation: "\"become extinct\" = bị tuyệt chủng." },
  { id: "anh10-9-14", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Reading", type: "tf", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nLast spring, students at a high school in Quang Ninh noticed that the beach near their school was covered with plastic waste after every storm. Instead of only complaining, they started a project called \"Blue Coast\". Every month, they organise clean-ups and record the types of rubbish they collect. They found that more than half of the waste was single-use plastic, such as bottles and food boxes. The students shared their data with local restaurants, and three of them have since stopped using plastic straws. The group's leader said that real change happens when people see the evidence with their own eyes.", statements: ["The students' project began after they noticed a problem near their school.","The students only clean the beach once a year.","Single-use plastic made up most of the waste they collected.","All restaurants in the area have stopped using plastic straws."], answer: [true,false,true,false], explanation: "a) Đúng. b) Sai: họ dọn dẹp hằng tháng. c) Đúng: hơn một nửa là nhựa dùng một lần. d) Sai: chỉ ba nhà hàng ngừng dùng ống hút nhựa." },
  { id: "anh10-9-15", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Rewrite each sentence so that its meaning stays the same, using the word(s) given in brackets.\na) \"I am cleaning the beach now,\" said Mai. (Mai said)\nb) \"We can save energy by turning off the lights,\" the teacher told us. (The teacher told us)\nc) He said, \"I saw a dolphin here yesterday.\" (He said)", answer: "a) Mai said (that) she was cleaning the beach then. b) The teacher told us (that) we could save energy by turning off the lights. c) He said (that) he had seen a dolphin there the day before.", explanation: "Mỗi câu 1/3 số điểm.\nLùi thì: am cleaning → was cleaning; can → could; saw → had seen.\nĐổi đại từ (I → she/he; we → we) và trạng từ (now → then; here → there; yesterday → the day before / the previous day).\nĐúng thì nhưng sai trạng từ: trừ một nửa điểm câu đó." },
  { id: "anh10-9-16", subject: "anh", grade: 10, chapter: "anh10-9", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Write a paragraph (about 100 words) about what students can do to protect the environment.", answer: "Đoạn văn khoảng 100 từ nêu những việc học sinh có thể làm để bảo vệ môi trường.", explanation: "Tiêu chí: câu chủ đề (2 điểm); ít nhất 3 hành động cụ thể có giải thích, dùng từ vựng chủ đề (pollution, raise awareness, habitat, recycle, endangered...) (4 điểm); câu kết (2 điểm); ngữ pháp, liên kết (2 điểm).\nBài mẫu: Although we are young, students can do many things to protect the environment. First, we can reduce waste by bringing our own water bottles and lunch boxes to school instead of buying drinks in plastic bottles. Second, we can save energy and water at home and at school, for example by turning off lights and taps when we do not need them. Third, we can join activities such as planting trees or cleaning beaches to protect the habitats of wild animals. Finally, we can raise awareness of environmental problems by sharing information on social media. Small actions like these can make a big difference." },
  { id: "anh10-10-01", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the word whose part in brackets is pronounced differently from the others. (Chọn từ có phần trong ngoặc [ ] phát âm khác)", options: ["tour[s]","guide[s]","trip[s]","tree[s]"], answer: 2, explanation: "\"trips\" có đuôi -s đọc /s/ (sau âm vô thanh /p/); các từ còn lại đọc /z/." },
  { id: "anh10-10-02", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\n___ is a form of tourism that protects nature and benefits local people.", options: ["Mass tourism","Space tourism","Ecotourism","Sightseeing"], answer: 2, explanation: "Ecotourism (du lịch sinh thái) bảo vệ thiên nhiên và mang lại lợi ích cho người dân địa phương." },
  { id: "anh10-10-03", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "practice", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nIf it ___ tomorrow, we will cancel our trip to Cuc Phuong National Park.", options: ["will rain","rains","rained","would rain"], answer: 1, explanation: "Câu điều kiện loại 1: If + hiện tại đơn, S + will + V → rains." },
  { id: "anh10-10-04", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Speaking & Communication", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Choose the most suitable response to complete the exchange.\nA: \"Excuse me, could you recommend an eco-friendly tour in the Mekong Delta?\"\nB: \"___\"", options: ["No, I'm not a tourist.","Have a nice day.","It costs a lot of money, doesn't it?","Sure. How about a two-day homestay tour in Ben Tre?"], answer: 3, explanation: "Đáp lại lời nhờ gợi ý bằng một gợi ý cụ thể: \"Sure. How about...?\"." },
  { id: "anh10-10-05", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nWhen visiting ethnic minority villages, tourists should respect local ___ and traditions, for example by asking for permission before taking photos.", options: ["costumes","customers","costs","customs"], answer: 3, explanation: "customs = phong tục; \"customs and traditions\" là cụm thường gặp." },
  { id: "anh10-10-06", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Reading", type: "tf", level: "TH", difficulty: 2, pool: "practice", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nTram Chim National Park in Dong Thap is a wetland area famous for its birds, especially the rare red-headed cranes. Many visitors come here on eco-tours, travelling by small boats through lotus fields and flooded forests. Local guides, who are often farmers living near the park, explain how the wetland is protected. Visitors are asked not to feed the birds or leave any rubbish behind. Part of the ticket money is used to protect the park, and local families earn extra income by selling handicrafts and serving traditional food.", statements: ["Tram Chim is well known for its bird life.","Visitors travel through the park by bus.","Some local guides are farmers who live near the park.","Tourists are encouraged to feed the birds."], answer: [true,false,true,false], explanation: "a) Đúng. b) Sai: đi bằng thuyền nhỏ. c) Đúng. d) Sai: du khách được yêu cầu không cho chim ăn." },
  { id: "anh10-10-07", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Pronunciation", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the word that differs from the other three in the position of the main stress. (Chọn từ có trọng âm chính khác)", options: ["natural","holiday","tourism","souvenir"], answer: 3, explanation: "souvenir /ˌsuːvəˈnɪə/ nhấn âm 3; natural, holiday, tourism nhấn âm 1." },
  { id: "anh10-10-08", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Vocabulary", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nOur ___ showed us around the national park and explained about the rare plants.", options: ["tourist","tour guide","passenger","customer"], answer: 1, explanation: "tour guide = hướng dẫn viên du lịch, người dẫn đoàn và giải thích." },
  { id: "anh10-10-09", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Vocabulary", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nEcotourism should be ___ so that future generations can also enjoy nature.", options: ["sustain","sustainably","sustainability","sustainable"], answer: 3, explanation: "Sau \"be\" cần tính từ → sustainable (bền vững)." },
  { id: "anh10-10-10", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Grammar", type: "mcq", level: "NB", difficulty: 1, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nIf I had more money, I ___ an eco-tour in the Amazon rainforest.", options: ["will join","join","would join","joined"], answer: 2, explanation: "Câu điều kiện loại 2 (không có thật ở hiện tại): If + quá khứ đơn, S + would + V → would join." },
  { id: "anh10-10-11", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Grammar", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nIf tourists ___ litter, the beach will stay clean and beautiful.", options: ["won't drop","didn't drop","wouldn't drop","don't drop"], answer: 3, explanation: "Điều kiện loại 1: mệnh đề \"if\" dùng hiện tại đơn → don't drop." },
  { id: "anh10-10-12", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Grammar", type: "mcq", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Choose the best option to complete the sentence.\nWe can't visit the cave because we don't have a local guide.\n→ If we ___ a local guide, we could visit the cave.", options: ["had","have","would have","will have"], answer: 0, explanation: "Tình huống không có thật ở hiện tại → điều kiện loại 2: If + quá khứ đơn (had), S + could + V." },
  { id: "anh10-10-13", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Reading", type: "mcq", level: "TH", difficulty: 2, pool: "exam", source: "Tự biên soạn", content: "Read the passage and choose the best option for the blank (___).\nWhen it is managed well, ecotourism can have a positive ___ on local communities. It creates jobs and helps people keep their traditional way of life.", options: ["effort","impact","affect","expense"], answer: 1, explanation: "\"have a positive impact on\" = có tác động tích cực đến." },
  { id: "anh10-10-14", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Reading", type: "tf", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Read the passage and decide whether each statement is True or False.\nEcotourism is often seen as a perfect solution: tourists enjoy nature, local people earn money, and the environment is protected. However, the reality is not always so simple. When a place becomes too popular, large numbers of visitors may damage the very nature they came to see. Some tour companies also call their trips \"eco-tours\" just to attract customers, even though they do little to protect the environment. To make ecotourism truly sustainable, experts suggest limiting the number of visitors, training local guides, and making sure that a fair share of the profits stays in the local community.", statements: ["The writer thinks ecotourism is always a perfect solution.","Too many visitors can harm natural areas.","Every tour called an \"eco-tour\" really protects the environment.","Experts recommend that local communities should benefit from ecotourism profits."], answer: [false,true,false,true], explanation: "a) Sai: \"the reality is not always so simple\". b) Đúng. c) Sai: một số công ty chỉ dùng tên \"eco-tour\" để thu hút khách. d) Đúng: \"a fair share of the profits stays in the local community\"." },
  { id: "anh10-10-15", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Rewrite each sentence so that its meaning stays the same, using the word(s) given in brackets.\na) If you don't follow the park rules, you will be fined. (Unless)\nb) I don't live near the sea, so I can't go diving often. (If)\nc) Leave the forest clean, or the animals will be harmed. (If you don't)", answer: "a) Unless you follow the park rules, you will be fined. b) If I lived near the sea, I could go diving often. c) If you don't leave the forest clean, the animals will be harmed.", explanation: "Mỗi câu 1/3 số điểm.\na) Unless = If ... not; sau \"Unless\" dùng động từ khẳng định.\nb) Sự thật hiện tại → điều kiện loại 2, đổi phủ định thành khẳng định: don't live → lived; can't → could.\nc) Câu mệnh lệnh + \"or\" → điều kiện loại 1 với \"If you don't...\"." },
  { id: "anh10-10-16", subject: "anh", grade: 10, chapter: "anh10-10", topic: "Writing", type: "essay", level: "VD", difficulty: 3, pool: "exam", source: "Tự biên soạn", content: "Write a paragraph (about 100 words) about an ecotourism destination in Viet Nam that you would like to visit. Say where it is, what you can do there and how tourists can protect it.", answer: "Đoạn văn khoảng 100 từ giới thiệu một điểm du lịch sinh thái ở Việt Nam: vị trí, hoạt động, cách bảo vệ.", explanation: "Tiêu chí: câu chủ đề (2 điểm); đủ 3 ý, dùng từ vựng chủ đề (ecotourism, local, sustainable, wildlife, tour guide...) và ít nhất một câu điều kiện (4 điểm); câu kết (2 điểm); ngữ pháp, liên kết (2 điểm).\nBài mẫu: I would love to visit Cuc Phuong National Park, which is about 120 kilometres south-west of Ha Noi. It is the oldest national park in Viet Nam and is home to many rare plants and animals. There, visitors can trek through the forest, see thousand-year-old trees and learn how endangered primates are rescued. To protect the park, tourists should stay on the paths, take their rubbish home and never disturb the animals. If every visitor follows these rules, the park will stay beautiful for future generations. I hope I can go there with my classmates next summer." }
);
